sqlite3 -header -column ../data/current.db <<'SQL'
WITH op AS (SELECT o.operation_id,o.opened_at_ms,ra.pool_id,pp.deadline_ms,CASE WHEN o.opened_at_ms<1777719600000 THEN 'reference' ELSE 'incident' END period FROM logical_operations o JOIN service_routes r ON r.route_id=o.route_id JOIN services s ON s.service_id=r.service_id JOIN route_assignments ra ON ra.route_id=o.route_id AND o.opened_at_ms>=ra.effective_from_ms AND o.opened_at_ms<ra.effective_to_ms JOIN policy_profiles pp ON pp.profile_id=ra.profile_id WHERE s.service_code='parcel-index' AND o.opened_at_ms>=1777716000000 AND o.opened_at_ms<1777723200000), a AS (SELECT op.*,COUNT(a.attempt_id) attempts,SUM(CASE WHEN f.is_success=0 THEN 1 ELSE 0 END) failed,MAX(a.attempt_no) maxno FROM op LEFT JOIN attempt_events a USING(operation_id) LEFT JOIN failure_codes f ON f.code_id=a.code_id GROUP BY op.operation_id), t AS (SELECT a.operation_id,f.is_success FROM attempt_events a JOIN failure_codes f USING(code_id) WHERE a.attempt_no=(SELECT max(x.attempt_no) FROM attempt_events x WHERE x.operation_id=a.operation_id)) SELECT period,pool_id,count(*) ops,sum(CASE WHEN t.is_success=0 THEN 1 ELSE 0 END) terminal,sum(attempts) attempts,sum(failed) failed,sum(attempts>1) retry,min(deadline_ms),max(deadline_ms) FROM a JOIN t USING(operation_id) GROUP BY period,pool_id;
SELECT w.pool_code,ts.signal_code,ts.unit,CASE WHEN x.measured_at_ms<1777719600000 THEN 'reference' ELSE 'incident' END period,avg(x.value) mean,count(*) n FROM telemetry_samples x JOIN telemetry_signals ts USING(signal_id) JOIN worker_pools w USING(pool_id) WHERE x.measured_at_ms>=1777716000000 AND x.measured_at_ms<1777723200000 AND x.pool_id IN (1,2) GROUP BY x.pool_id,ts.signal_id,period ORDER BY pool_code,signal_code,period;
SQL

